//
// Instruction matrix parity test: every instruction x addressing mode x size
// case in data/golden/asm/matrix/*.tsv must assemble to the same object
// bytes, with the same kind of diagnostic (none / warning / error), as in the
// ORIGINAL EASy68K assembler. The data is generated by the reference oracle
// (tools/reference/gen_instruction_matrix.py); see that script for the case
// layout. Each case is assembled at $1000 with BK (a backward reference), RL
// (a register list) and FW (a forward reference) in scope:
//
//   BK EQU $1F00
//   RL REG D2-D4/A3
//    ORG $1000
//    <case>
//   FW EQU $1F00
//    END $1000
//
// Set EASY68K_MATRIX_DUMP=<file> to write every mismatch to <file>.

#include <gtest/gtest.h>

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "easym68k/asm/assembler.h"

namespace easym68k::asm_ {
namespace {

std::filesystem::path MatrixDir() {
  std::filesystem::path p = std::filesystem::current_path();
  for (int i = 0; i < 5; ++i) {
    if (std::filesystem::exists(p / "data" / "golden" / "asm" / "matrix"))
      return p / "data" / "golden" / "asm" / "matrix";
    p = p.parent_path();
  }
  return "data/golden/asm/matrix";
}

std::vector<std::string> MatrixFiles() {
  std::vector<std::string> names;
  std::error_code ec;
  for (const auto& e : std::filesystem::directory_iterator(MatrixDir(), ec))
    if (e.path().extension() == ".tsv")
      names.push_back(e.path().stem().string());
  std::sort(names.begin(), names.end());
  return names;
}

struct Case {
  std::string source;
  std::string hex;   // expected object bytes
  std::string diag;  // "-" or "ERROR: ..." / "WARNING: ..."
};

std::vector<Case> ReadCases(const std::string& name) {
  std::vector<Case> cases;
  std::ifstream in(MatrixDir() / (name + ".tsv"));
  for (std::string line; std::getline(in, line);) {
    if (!line.empty() && line.back() == '\r')
      line.pop_back();
    size_t t1 = line.find('\t');
    size_t t2 = line.find('\t', t1 + 1);
    if (t1 == std::string::npos || t2 == std::string::npos)
      continue;
    cases.push_back({line.substr(0, t1), line.substr(t1 + 1, t2 - t1 - 1), line.substr(t2 + 1)});
  }
  return cases;
}

// 0 = none, 1 = warning, 2 = error.
int DiagClass(const std::string& diag) {
  if (diag.rfind("ERROR", 0) == 0)
    return 2;
  if (diag.rfind("WARNING", 0) == 0)
    return 1;
  return 0;
}

const char* ClassName(int c) {
  return c == 2 ? "error" : c == 1 ? "warning" : "none";
}

constexpr int kCaseLine = 4;

struct Outcome {
  std::string hex;
  int diag_class = 0;
  std::string message;
};

Outcome AssembleCase(const std::string& source) {
  Assembler assembler;
  AssemblyResult r = assembler.Assemble("BK EQU $1F00\nRL REG D2-D4/A3\n ORG $1000\n " + source +
                                        "\nFW EQU $1F00\n END $1000\n");
  Outcome out;
  if (r.org == 0x1000 || r.code.empty()) {
    char buf[3];
    for (uint8_t b : r.code) {
      std::snprintf(buf, sizeof(buf), "%02X", b);
      out.hex += buf;
    }
  } else {
    out.hex = "<org " + std::to_string(r.org) + ">";
  }
  for (const auto& e : r.errors) {
    if (e.line_number != kCaseLine)
      continue;
    int c = e.severity == ErrorSeverity::kWarning ? 1 : 2;
    if (c > out.diag_class) {
      out.diag_class = c;
      out.message = e.message;
    }
  }
  return out;
}

class InstructionMatrixTest : public ::testing::TestWithParam<std::string> {};

TEST_P(InstructionMatrixTest, MatchesOriginalAssembler) {
  const std::vector<Case> cases = ReadCases(GetParam());
  ASSERT_FALSE(cases.empty()) << "no cases for " << GetParam();

  const char* dump_path = std::getenv("EASY68K_MATRIX_DUMP");
  std::ofstream dump;
  if (dump_path)
    dump.open(dump_path, std::ios::app);

  int mismatches = 0;
  std::ostringstream examples;
  for (const Case& c : cases) {
    Outcome got = AssembleCase(c.source);
    int want_class = DiagClass(c.diag);
    // The original builds instructions with an undefined symbol from an
    // uninitialized value (EVAL.CPP evalNumber() leaves it unset), so only
    // the instruction length is compared for those.
    bool undefined = c.diag == "ERROR: Undefined symbol";
    bool bytes_match = undefined ? got.hex.size() == c.hex.size() : got.hex == c.hex;
    if (bytes_match && got.diag_class == want_class)
      continue;
    ++mismatches;
    std::ostringstream m;
    m << c.source << "\n    want: [" << c.hex << "] " << ClassName(want_class) << " (" << c.diag
      << ")\n    got:  [" << got.hex << "] " << ClassName(got.diag_class) << " (" << got.message
      << ")\n";
    if (mismatches <= 10)
      examples << m.str();
    if (dump.is_open())
      dump << m.str();
  }
  EXPECT_EQ(mismatches, 0) << GetParam() << ": " << mismatches << " of " << cases.size()
                           << " cases differ from the original; first ones:\n"
                           << examples.str();
}

INSTANTIATE_TEST_SUITE_P(Matrix, InstructionMatrixTest, ::testing::ValuesIn(MatrixFiles()),
                         [](const ::testing::TestParamInfo<std::string>& info) {
                           return info.param;
                         });

}  // namespace
}  // namespace easym68k::asm_
